import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"歸妹","description":"周易正義 - 歸妹","frontmatter":{"title":"歸妹","description":"周易正義 - 歸妹"},"headers":[],"relativePath":"classics/zhengyi/054.md","filePath":"classics/zhengyi/054.md"}'),l={name:"classics/zhengyi/054.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>雷澤歸妹</p></blockquote><blockquote><p>卦辭：徵兇，無攸利。</p></blockquote><blockquote><p>彖曰：歸妹，天地之大義也。天地不交而萬物不興。歸妹，人之終始也。說以動，所歸妹也。徵兇”，位不當也。無攸利，柔乘剛也。</p></blockquote><h1 id="歸妹" tabindex="-1">歸妹 <a class="header-anchor" href="#歸妹" aria-label="Permalink to “歸妹”">​</a></h1><p>王弼：妹者，少女之稱也。兌為少陰，震為長陽，少陰而乘長陽，說以動，嫁妹之象也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：歸妹者，卦名也。婦人謂嫁曰歸，“歸妹”猶言嫁妹也。然《易》論歸妹得名不同，《泰卦》六五雲：“帝乙歸妹。”彼據兄嫁妹謂之“歸妹”。此卦名歸妹，以妹從娣而嫁，謂之“歸妹”。故初九爻辭雲“歸妹以娣是”也。上鹹卦明二少相感，恆卦明二長相承，今此卦以少承長，非是匹敵，明是妹從娣嫁，故謂之歸妹焉。古者諸侯一取九女，嫡夫人及左右媵皆以侄娣從，故以此卦當之矣。不言歸侄者，女娣是兄弟之行，亦舉尊以包之也。“徵兇，無攸利”者，歸妹之戒也。徵謂進有所往也。妹從娣嫁，本非正匹，唯須自守卑退以事元妃。若妾進求寵，則有並後兇咎之敗，故曰“徵兇，無攸利”。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="歸妹-天地之大義也。天地不交-而萬物不興。歸妹-人之終始也。-​" tabindex="-1">歸妹，天地之大義也。天地不交，而萬物不興。歸妹，人之終始也。 ​ <a class="header-anchor" href="#歸妹-天地之大義也。天地不交-而萬物不興。歸妹-人之終始也。-​" aria-label="Permalink to “歸妹，天地之大義也。天地不交，而萬物不興。歸妹，人之終始也。 ​”">​</a></h3><p>王弼：陰陽既合，長少又交，“天地之大義”，人倫之終始。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“歸妹，天地之大義也。天地不交，而萬物不興”者，此舉天地交合，然後萬物蕃興，證美歸妹之義。所以未及釋卦名，先引證者，以歸妹之義，非人情所欲，且違於匹對之理。蓋以聖人制禮，令侄娣從其姑娣而充妾媵者，所以廣其繼嗣，以象天地以少陰少陽、長陰長陽之氣共相交接，所以蕃興萬物也。“歸妹，人之終始也”者，上既引天地交合為證，此又舉人事“歸妹”結合其義也。天地以陰陽相合而得生物不已，人倫以長少相交而得繼嗣不絕，歸妹豈非“天地之大義，人倫之終始”也？</p><h3 id="說以動-所歸妹也。-​" tabindex="-1">說以動，所歸妹也。 ​ <a class="header-anchor" href="#說以動-所歸妹也。-​" aria-label="Permalink to “說以動，所歸妹也。 ​”">​</a></h3><p>王弼：少女而與長男交，少女所不樂也。而今“說以動”，所歸必妹也。雖與長男交，嫁而系娣，是以“說”也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：此就二體釋歸妹之義。少女而與長男交，少女所不樂也。而今“說以動”所歸必妹也，雖與長男交，嫁而系於娣，是以說也。系娣所以說者，既系娣為媵，不得別適，若其不以備數，更有動望之憂，故系娣而行合禮，“說以動”也。</p><h3 id="徵兇-位不當也。-​" tabindex="-1">“徵兇”，位不當也。 ​ <a class="header-anchor" href="#徵兇-位不當也。-​" aria-label="Permalink to ““徵兇”，位不當也。 ​”">​</a></h3><p>王弼：履於，皆不當位，釋“徵兇”之義。位既不當，明非正嫡，因說動而更求進，妖邪之道也，所戒其“徵兇”也。</p><h3 id="無攸利-柔乘剛也。-​" tabindex="-1">“無攸利”，柔乘剛也。 ​ <a class="header-anchor" href="#無攸利-柔乘剛也。-​" aria-label="Permalink to ““無攸利”，柔乘剛也。 ​”">​</a></h3><p>王弼：以徵則有不正之兇，以處則有乘剛之逆。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>“無攸利，柔乘剛也”。○正義曰：此因六三、六五乘剛，釋“無攸利”之義。夫陽貴而陰賤，以妾媵之賤，進求殊寵，即是以賤陵貴，故無施而利也。○注“以徵則”至“有乘剛之逆也”。○正義曰：《彖》以失位釋“徵兇”，乘剛釋“無攸利”，而《注》連引言之者，《略例》雲：“去初、上而論位分，則三、五各在一卦之上，何得不謂之陽？三、四各在一卦之下，何得不謂之陰？然則二、四陰位也，三、五陽位也。”陽應在上，陰應在下，今二、三、四、五，並皆失位，其勢自然柔皆乘剛，其猶妾媵求寵，其勢自然以賤陵貴，以明柔之乘剛，緣於失正而進也。</p><h2 id="《象》曰-澤上有雷-歸妹。君子以求終知敝。-​" tabindex="-1">《象》曰：澤上有雷，歸妹。君子以求終知敝。 ​ <a class="header-anchor" href="#《象》曰-澤上有雷-歸妹。君子以求終知敝。-​" aria-label="Permalink to “《象》曰：澤上有雷，歸妹。君子以求終知敝。 ​”">​</a></h2><p>王弼：歸妹，相終始之道也，故以“永終知敝”。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“澤上有雷”，“說以動”也。故曰“歸妹君子以永終知敝”者，“歸妹相終始之道也”，故君子象此以永長其終，知應有不終之敝故也。</p><h2 id="初九-歸妹以娣-跛能履-徵吉。-​" tabindex="-1">初九：歸妹以娣，跛能履，徵吉。 ​ <a class="header-anchor" href="#初九-歸妹以娣-跛能履-徵吉。-​" aria-label="Permalink to “初九：歸妹以娣，跛能履，徵吉。 ​”">​</a></h2><p>王弼：少女而與長男為耦，非敵之謂，是娣從之義也。妹，少女之稱也。少女之行，善莫若娣。夫承嗣以君之子，雖幼而不妄行，少女以娣，雖“跛能履”，斯乃恆久之義，吉而相承之道也。以斯而進，吉其宜也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“初九”至“貞吉”。○正義曰：“歸妹以娣”者，少女謂之妹，從娣而行謂之歸。初九以兌適震，非夫婦匹敵，是從娣之義也，故曰“歸妹以娣”也。“跛能履”者，妹而繼姊為娣，雖非正配，不失常道，譬猶跛人之足然。雖不正，不廢能履，故曰“跛能履”也。“徵吉”者，少長非偶，為妻而行則兇焉，為娣而行則吉，故曰“徵吉”也。○注“夫承嗣以君之子”至“吉其宜也”。○正義曰：“夫承嗣以君之子，雖幼而不妄行”者，此為少女作此例也。言君之子宜為嗣承，以類妃之妹應為娣也。立嗣宜取長，然君之子雖幼而立之，不為妄也。以言行嫁宜匹敵。然妃之妹雖至少，而為娣則可行也。</p><h3 id="《象》曰-歸妹以娣-以恆也。-跛能履-吉相承也。-​" tabindex="-1">《象》曰：“歸妹以娣”，以恆也。“跛能履”，吉相承也。 ​ <a class="header-anchor" href="#《象》曰-歸妹以娣-以恆也。-跛能履-吉相承也。-​" aria-label="Permalink to “《象》曰：“歸妹以娣”，以恆也。“跛能履”，吉相承也。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“以恆也”者，妹而為娣，恆久之道也。“吉相承也”者，行得其宜，是相承之道也。</p><h2 id="九二-眇能視-利幽人之貞。-​" tabindex="-1">九二：眇能視，利幽人之貞。 ​ <a class="header-anchor" href="#九二-眇能視-利幽人之貞。-​" aria-label="Permalink to “九二：眇能視，利幽人之貞。 ​”">​</a></h2><p>王弼：雖失其位，而居內處中，眇猶能視，足以保常也。在內履中，而能守其常，故”利幽人之貞“也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：九二不雲歸妹者，既在歸妹之卦，歸妹可知，故無不言也。然九二雖失其位，不廢居內處中。以言歸妹，雖非正配，不失交合之道，猶如眇目之人，視雖不正，不廢能視耳，故曰“眇能視”也。“利幽人之貞”者，居內處中，能守其常，施之於人，是處幽而不失其貞正也。故曰“利幽人之貞也”。</p><h3 id="《象》曰-利幽人之貞-未變常也。-​" tabindex="-1">《象》曰：“利幽人之貞”，未變常也。 ​ <a class="header-anchor" href="#《象》曰-利幽人之貞-未變常也。-​" aria-label="Permalink to “《象》曰：“利幽人之貞”，未變常也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“未變常也”者，貞正者人之常也，九三失位，嫌其變常不貞也，能以履中不偏，故云“未變常”也。</p><h2 id="六三-歸妹以須-反歸以娣。-​" tabindex="-1">六三：歸妹以須，反歸以娣。 ​ <a class="header-anchor" href="#六三-歸妹以須-反歸以娣。-​" aria-label="Permalink to “六三：歸妹以須，反歸以娣。 ​”">​</a></h2><p>王弼：室主猶存，而求進焉。進未值時，故有須也。不可以進，故“反歸”待時，“以娣”乃行也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“歸妹以須”者，六三在“歸妹”之時，處下體之上，有欲求為室主之象，而居不當位，則是室主獨存，室主既存，而欲求進，為末值其時也。未當其時，則宜有待，故曰“歸妹以須也”。“反歸以娣”者，既而有須，不可以進，宜反歸待時，以娣乃行，故曰“反歸以娣”。</p><h3 id="《象》曰-歸妹以須-未當也。-​" tabindex="-1">《象》曰：“歸妹以須”，未當也。 ​ <a class="header-anchor" href="#《象》曰-歸妹以須-未當也。-​" aria-label="Permalink to “《象》曰：“歸妹以須”，未當也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“未當也”者，未當其時，故宜有待也。</p><h2 id="九四-歸妹愆期-遲歸有時。-​" tabindex="-1">九四：歸妹愆期，遲歸有時。 ​ <a class="header-anchor" href="#九四-歸妹愆期-遲歸有時。-​" aria-label="Permalink to “九四：歸妹愆期，遲歸有時。 ​”">​</a></h2><p>王弼：夫以不正無應而適人也，必須彼道窮盡，無所與交，然後乃可以往，故“愆期遲歸”，以待時也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：九四居下得位，又無其應，以斯適人，“必待彼道窮盡，無所與交，然後乃可以往”，故曰“愆期遲歸有時”也。</p><h3 id="《象》曰-愆期-之志-有待而行也。-​" tabindex="-1">《象》曰：“愆期”之志，有待而行也。 ​ <a class="header-anchor" href="#《象》曰-愆期-之志-有待而行也。-​" aria-label="Permalink to “《象》曰：“愆期”之志，有待而行也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：嫁宜及時。今乃過期而遲歸者，此嫁者之志，正欲有所待而後乃行也。</p><h2 id="六五-帝乙歸妹-其君之袂-不如其娣之袂良。月幾望-吉。-​" tabindex="-1">六五：帝乙歸妹，其君之袂，不如其娣之袂良。月幾望，吉。 ​ <a class="header-anchor" href="#六五-帝乙歸妹-其君之袂-不如其娣之袂良。月幾望-吉。-​" aria-label="Permalink to “六五：帝乙歸妹，其君之袂，不如其娣之袂良。月幾望，吉。 ​”">​</a></h2><p>王弼：歸妹之中，獨處貴位，故謂之“帝乙歸妹”也。袂，衣袖，所以為禮容者也。“其君之袂”，為帝乙所寵也，即五也。為帝乙所崇飾，故謂之“其君之袂”也。配在九二，兌少震長，以長從少，不若以少從長之為美也，故曰“不若其娣之袂良”也。位在乎中，以貴而行，極陰之盛，以斯適配，雖不若少，往亦必合，故曰“月幾望，吉”也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>“六五帝乙”至“幾望吉”。○正義曰：“帝乙歸妹”者，六五居歸妹之中，“獨處貴位”，是帝王之所嫁妹也，故曰“帝乙歸妹”。“其君之袂，不如其娣之袂良”者，六五雖處貴位，卦是長陽之卦，若以爻為人，即是婦人之道，故為帝乙之妹。既居長卦，乃是長女之象，其君即五也。袂，衣袖也，所舉斂以為禮容，帝王嫁妹，為之崇飾，故曰“其君之袂”也。“配在九二，兌少震長，以長從少”者，可以從少，雖有其君崇飾之袂，猶不若以少從長之為美，故曰“不如其娣之袂良”也。“月幾望吉”者，陰而貴盛，如月之近望，以斯適配，雖不如以少從長，然以貴而行，往必合志，故得吉也，故曰“月幾望，吉”也。</p><h3 id="《象》曰-帝乙歸妹-不如其娣之袂良-也。其位在中-以貴行也。-​" tabindex="-1">《象》曰：“帝乙歸妹，不如其娣之袂良”也。其位在中，以貴行也。 ​ <a class="header-anchor" href="#《象》曰-帝乙歸妹-不如其娣之袂良-也。其位在中-以貴行也。-​" aria-label="Permalink to “《象》曰：“帝乙歸妹，不如其娣之袂良”也。其位在中，以貴行也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>“象曰”至“以貴行也”。○正義曰：“帝乙歸妹，不如其娣之袂良”者，釋其六五雖所居貴位，言長不如少也，言不必少女，而從於長男也。“其位在中，以貴行也”者，釋“月幾望，吉”也。既以長適少，非歸妹之美而得吉者，其位在五之中，以貴盛而行，所往必得合，而獲吉也。</p><h2 id="上六-女承筐-無實-士刲羊-無血-無攸利。-​" tabindex="-1">上六：女承筐，無實，士刲羊，無血，無攸利。 ​ <a class="header-anchor" href="#上六-女承筐-無實-士刲羊-無血-無攸利。-​" aria-label="Permalink to “上六：女承筐，無實，士刲羊，無血，無攸利。 ​”">​</a></h2><p>王弼：羊謂三也。處卦之窮，仰無所承，下又無應，為女而承命，則筐虛而莫之與。為士而下命，則“刲羊”而“無血”。“刲血”而“無血”，不應所命也。進退莫與，故曰“無攸利”也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>“上六”至“無攸利”。○正義曰：女之為行，以上有承順為美；士之為功，以下有應命為貴，上六處卦之窮，仰則無所承受，故為女承筐，則虛而無實。又下無其應，下命則無應之者，故為“士刲羊”則乾而“無和”，故曰“女承筐，無實，士刲羊無血。”則進退莫與，故無所利。</p><h3 id="《象》曰-上六-無實-承虛筐也。-​" tabindex="-1">《象》曰：上六“無實”，承虛筐也。 ​ <a class="header-anchor" href="#《象》曰-上六-無實-承虛筐也。-​" aria-label="Permalink to “《象》曰：上六“無實”，承虛筐也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“承虛筐”者，筐本盛幣，以幣為實。今之“無實”，正是承捧虛筐，空無所有也。</p>',68)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
